package io.github.artisanguillonrenov.cortana.core.voice

import kotlin.math.sqrt

/**
 * Voice-embedding matcher adapted for Cortana from the identification strategy in
 * InterGenJLU/jarvis (MIT; see docs/third_party/JARVIS_INTERGEN_MIT.txt).
 *
 * This class ONLY compares speaker embeddings generated by the same external/local encoder.
 * It does not infer a speaker from a transcript and does not grant permissions.
 * A match is a conversation-personalization hint, NEVER owner authentication.
 * Embeddings are held in memory and are not persisted or sent to another service here.
 */
class SpeakerMatcher(
    private val minSimilarity: Double = 0.70,
    private val minSeparation: Double = 0.06,
) {
    init {
        require(minSimilarity in -1.0..1.0) { "Invalid cosine threshold" }
        require(minSeparation in 0.0..2.0) { "Invalid separation margin" }
    }

    enum class Outcome { MATCH, NO_PROFILES, INVALID_VECTOR, INCOMPATIBLE_MODEL, BELOW_THRESHOLD, AMBIGUOUS }

    data class Result(
        val profileId: String?,
        /** Cosine similarity, NOT an authentication confidence or a probability. */
        val similarity: Double?,
        val outcome: Outcome,
    )

    private val profiles = linkedMapOf<String, DoubleArray>()
    private var dimensions: Int? = null

    /** Averages at least two enrollment samples. Rejects NaNs, zero vectors and mixed dimensions. */
    @Synchronized
    fun enroll(profileId: String, samples: List<FloatArray>): Boolean {
        require(profileId.isNotBlank()) { "Profile ID cannot be empty" }
        if (samples.size < 2) return false
        val vectors = samples.map { normalize(it) ?: return false }
        val size = vectors.first().size
        if (vectors.any { it.size != size } || (dimensions != null && dimensions != size)) return false
        val sum = DoubleArray(size)
        for (sample in vectors) for (i in 0 until size) sum[i] += sample[i]
        val prototype = normalize(sum) ?: return false
        profiles[profileId] = prototype
        dimensions = size
        return true
    }

    @Synchronized
    fun identify(embedding: FloatArray): Result {
        if (profiles.isEmpty()) return Result(null, null, Outcome.NO_PROFILES)
        val candidate = normalize(embedding) ?: return Result(null, null, Outcome.INVALID_VECTOR)
        if (candidate.size != dimensions) return Result(null, null, Outcome.INCOMPATIBLE_MODEL)
        val ranked = profiles.entries.map { (id, vector) ->
            id to vector.indices.sumOf { i -> vector[i] * candidate[i] }.coerceIn(-1.0, 1.0)
        }.sortedByDescending { it.second }
        val best = ranked.first()
        if (best.second < minSimilarity) return Result(null, best.second, Outcome.BELOW_THRESHOLD)
        if (ranked.size > 1 && best.second - ranked[1].second < minSeparation)
            return Result(null, best.second, Outcome.AMBIGUOUS)
        return Result(best.first, best.second, Outcome.MATCH)
    }

    @Synchronized
    fun remove(profileId: String) {
        profiles.remove(profileId)
        if (profiles.isEmpty()) dimensions = null
    }

    @Synchronized
    fun clear() {
        profiles.clear()
        dimensions = null
    }

    @Synchronized
    fun profileCount(): Int = profiles.size

    private fun normalize(values: FloatArray): DoubleArray? {
        if (values.size !in 8..4096 || values.any { !it.isFinite() }) return null
        return normalize(DoubleArray(values.size) { values[it].toDouble() })
    }

    private fun normalize(values: DoubleArray): DoubleArray? {
        if (values.any { !it.isFinite() }) return null
        val squared = values.sumOf { it * it }
        if (!squared.isFinite() || squared <= 1e-12) return null
        val norm = sqrt(squared)
        return DoubleArray(values.size) { values[it] / norm }
    }
}
